from collections import deque
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def fifo_report(trades: list[dict]) -> dict:
    if not isinstance(trades, list):
        raise ValueError('trades must be a list')
    cent = Decimal('0.01')
    four_places = Decimal('0.0001')
    zero = Decimal('0')
    lots = deque()
    sales = []
    total_realized = Decimal('0.00')
    for trade in trades:
        if not isinstance(trade, dict):
            raise ValueError('trade must be a dict')
        if 'date' not in trade or 'side' not in trade or 'quantity' not in trade or 'price' not in trade:
            raise ValueError('trade missing required key')
        date_value = trade['date']
        if not isinstance(date_value, str):
            raise ValueError('invalid date')
        if len(date_value) != 10 or date_value[4] != '-' or date_value[7] != '-':
            raise ValueError('invalid date')
        year_part = date_value[0:4]
        month_part = date_value[5:7]
        day_part = date_value[8:10]
        for part in (year_part, month_part, day_part):
            for ch in part:
                if ch < '0' or ch > '9':
                    raise ValueError('invalid date')
        try:
            date(int(year_part), int(month_part), int(day_part))
        except ValueError:
            raise ValueError('invalid date') from None
        side = trade['side']
        if side != 'BUY' and side != 'SELL':
            raise ValueError('invalid side')
        quantity = trade['quantity']
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('invalid quantity')
        price_value = trade['price']
        if not isinstance(price_value, str):
            raise ValueError('invalid price')
        try:
            price = Decimal(price_value)
        except (InvalidOperation, ValueError, ArithmeticError):
            raise ValueError('invalid price') from None
        if not price.is_finite():
            raise ValueError('invalid price')
        if price <= zero:
            raise ValueError('invalid price')
        if price.as_tuple().exponent < -4:
            raise ValueError('invalid price')
        if 'fee' in trade:
            fee_value = trade['fee']
        else:
            fee_value = '0.00'
        if not isinstance(fee_value, str):
            raise ValueError('invalid fee')
        try:
            fee = Decimal(fee_value)
        except (InvalidOperation, ValueError, ArithmeticError):
            raise ValueError('invalid fee') from None
        if not fee.is_finite():
            raise ValueError('invalid fee')
        if fee < zero:
            raise ValueError('invalid fee')
        if fee.as_tuple().exponent < -2:
            raise ValueError('invalid fee')
        if side == 'BUY':
            lots.append([quantity, quantity * price + fee])
        else:
            inventory = 0
            for lot in lots:
                inventory += lot[0]
            if inventory < quantity:
                raise ValueError('insufficient inventory')
            to_sell = quantity
            exact_cost = Decimal('0')
            while to_sell > 0:
                lot = lots[0]
                q = lot[0]
                c = lot[1]
                taken = q if q < to_sell else to_sell
                consumed = c * taken / q
                exact_cost += consumed
                lot[0] = q - taken
                lot[1] = c - consumed
                to_sell -= taken
                if lot[0] == 0:
                    lots.popleft()
            exact_proceeds = quantity * price - fee
            proceeds_q = exact_proceeds.quantize(cent, rounding=ROUND_HALF_UP)
            cost_q = exact_cost.quantize(cent, rounding=ROUND_HALF_UP)
            realized_q = (exact_proceeds - exact_cost).quantize(cent, rounding=ROUND_HALF_UP)
            sales.append({'date': date_value, 'quantity': quantity, 'proceeds': proceeds_q, 'cost': cost_q, 'realized': realized_q})
            total_realized += realized_q
    remaining = []
    inventory_quantity = 0
    for lot in lots:
        q = lot[0]
        c = lot[1]
        if q > 0:
            inventory_quantity += q
            remaining.append({'quantity': q, 'unit_cost': (c / q).quantize(four_places, rounding=ROUND_HALF_UP), 'total_cost': c.quantize(cent, rounding=ROUND_HALF_UP)})
    return {'sales': sales, 'total_realized': total_realized.quantize(cent, rounding=ROUND_HALF_UP), 'remaining': remaining, 'inventory_quantity': inventory_quantity}
